import { test, expect } from '@playwright/test';

import { test, expect, tekton } from '@playwright/test';

// Define the test suite for login functionality
test('Perform Login Operation on Practice Expand Testing Login Page', async ({ page }) => {
  // Navigate to the login page
  await page.goto('https://practice.expandtesting.com/login');

  // Assert the page title
  await expect(page).toHaveTitle(/Test Login Page/);

  // Assert the presence of page headings
  const headings = [
    { tag: 'h1', text: 'Test Login page for Automation Testing Practice' },
    { tag: 'h2', text: 'How to test the login page?' },
    { tag: 'h3', text: 'How Does Form-Based Authentication Work?' },
    { tag: 'h2', text: 'Login Automation Test Cases' },
    { tag: 'h2', text: 'Login Automation Test Cases' },
    { tag: 'h3', text: 'Test Case 1: Successful Login' }
  ];

  for (const heading of headings) {
    await expect(page.locator(heading.tag, { hasText: heading.text })).toBeVisible();
  }

  // Assert the presence of inputs
  const inputs = [
    { selector: '#username', type: 'text', id: 'username', name: 'username', label: 'Username' },
    { selector: '#password', type: 'password', id: 'password', name: 'password', label: 'Password' }
  ];

  for (const input of inputs) {
    await expect(page.locator(input.selector, { hasValue: input.label })).toBeVisible();
  }

  // Assert the presence of button
  await expect(page.locator('#submit-login', { hasText: 'Login' })).toBeVisible();

  // Perform login operation with valid credentials
  await page.fill('#username', 'practice');
  await page.fill('#password', 'password');
  await page.click('#submit-login');

  // Assert the page title after successful login
  await expect(page).toHaveTitle(/Welcome to the Secure Area/);

  // Assert the presence of success message
  await expect(page.locator('#submit-login', { hasText: 'Logout' })).toBeVisible();

  // Perform login operation with invalid credentials
  await page.fill('#username', 'invalidUser');
  await page.fill('#password', 'invalidPassword');
  await page.click('#submit-login');

  // Assert the error message for invalid credentials
  await expect(page.locator('.error-message')).toContainText('Invalid username or password');

  // Handle loading states and dynamic content
  // This is a placeholder for potential handling of dynamic elements or loading states
  // For example, if elements are dynamically added or loaded, you might want to add checks here

  // Perform accessibility checks (example: checking if login button is keyboard accessible)
  // This is a placeholder for accessibility checks, you should implement actual checks based on your needs
  await expect(page.getByRole('button', { name: 'Login' })).toBeEnabled();
  await expect(page.getByRole('button', { name: 'Login' })).toBeClickable();
});

// Test for async operations (e.g., waiting for page to load)
test.afterEach(async ({ page }) => {
  await page.waitForTimeout(1000); // Simulate a delay for async operations
});

This test script uses Playwright to navigate to the specified URL, fill in the login credentials, and verify the expected outcomes. It also includes assertions for the presence of page elements, validation of successful and invalid login attempts, and a placeholder for handling dynamic elements or loading states. Accessibility checks are also included as a placeholder for ensuring the login button is accessible.

